#include "../verification/fresh_fixture_helpers.hpp"
// Native aggregation of recorded profiling values. No solver or replay launch.
int main(int argc,char**argv){try{require(argc==4,"usage: profile_training MATRIX CAMPAIGN NEW_PROFILE.json");auto matrix=read_json(argv[1]);files::path campaign=argv[2];std::ostringstream out;out<<std::setprecision(17)<<"{\"kind\":\"n83_recorded_training_profiles\",\"matrix_sha256\":"<<qstr(digest(argv[1]))<<",\"runs\":[";bool first=true;
 for(auto&entry:matrix.at("rows").array){if(entry.at("method").scalar!="ic")continue;auto id=entry.at("id").scalar;auto dir=campaign/id;auto execution=read_json((dir/"execution.json").string());if(!first)out<<",";first=false;out<<"{\"id\":"<<qstr(id)<<",\"candidate\":"<<qstr(entry.at("candidate").at("id").scalar)<<",\"status\":"<<qstr(execution.at("status").scalar)<<",\"wall_s\":"<<execution.at("elapsed_process_wall_s").scalar<<",\"cpu_total_s\":"<<execution.at("cpu_total_s").scalar<<",\"peak_rss_bytes\":"<<execution.at("peak_rss_bytes").scalar<<",\"memory_limit_hit\":null";
 auto summary_rows=lines(dir/"stdout.jsonl");const J*summary=nullptr;for(auto&r:summary_rows)if(r.at("kind").scalar=="compact_orbit_dlp_summary")summary=&r;
 if(summary){out<<",\"producer_phase_ms\":{";bool f=true;for(auto&[key,v]:summary->at("timing_ms").object){if(!f)out<<",";f=false;out<<qstr(key)<<":"<<v.scalar;}out<<"}";}
 if(files::is_regular_file(dir/"rank.jsonl")){auto trace=lines(dir/"rank.jsonl");uint64_t attempts=0,relations=0,gains=0,probes=0,states=0,prior_io_ns=0;std::map<std::string,U>phase;std::vector<std::string> curve;
 for(auto&r:trace){auto kind=r.at("kind").scalar;if(kind=="n83_rank_attempt_end"){attempts++;relations+=truth(r.at("found"));gains+=truth(r.at("gained"));probes+=uint64_t(num(r.at("probes")));states+=uint64_t(num(r.at("states")));for(auto&[key,v]:r.at("timing_ns").object)phase[key]+=num(v);std::ostringstream point;point<<"{\"attempt\":"<<dec(num(r.at("attempt")))<<",\"rank\":"<<dec(num(r.at("rank_after")))<<",\"probes\":"<<dec(num(r.at("probes")))<<",\"search_ns\":"<<dec(num(r.at("timing_ns").at("relation_search_excluding_checks")))<<",\"rss_bytes\":"<<r.at("memory").at("rss_bytes").scalar<<",\"hwm_bytes\":"<<r.at("memory").at("hwm_bytes").scalar<<"}";curve.push_back(point.str());}else if(kind=="n83_rank_solution")phase["backsolve"]+=num(r.at("backsolve_ns"));else if(kind=="n83_rank_trace_end")prior_io_ns=uint64_t(num(r.at("prior_trace_write_flush_ns")));}
 out<<",\"attempts\":"<<attempts<<",\"useful_relations\":"<<relations<<",\"rank_gain\":"<<gains<<",\"probes\":"<<probes<<",\"states\":"<<states<<",\"phase_sum_ns\":{";bool f=true;for(auto&[key,value]:phase){if(!f)out<<",";f=false;out<<qstr(key)<<":"<<dec(value);}out<<"},\"prior_trace_format_write_flush_ns\":"<<prior_io_ns<<",\"rank_curve\":[";for(size_t i=0;i<curve.size();i++){if(i)out<<",";out<<curve[i];}out<<"]";}
 out<<",\"stdout_sha256\":"<<qstr(digest(dir/"stdout.jsonl"))<<",\"execution_sha256\":"<<qstr(digest(dir/"execution.json"))<<"}";
 }
 out<<"],\"aggregation_source_sha256\":"<<qstr(digest(__FILE__))<<",\"aggregation_binary_sha256\":"<<qstr(digest(argv[0]))<<"}\n";create_new(argv[3],out.str());std::cout<<"Recorded profiles aggregated natively\n";return 0;}catch(const std::exception&e){std::cerr<<"FAIL: "<<e.what()<<"\n";return 1;}}
